CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <cublasLt.h>
#include <stdexcept>

// Fused divide+GELU elementwise kernel as fallback
__global__ void __launch_bounds__(256)
divide_gelu_kernel(const float* __restrict__ input,
                   float* __restrict__ output,
                   int numel,
                   float inv_divisor) {
    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    if (idx + 3 < numel) {
        float4 v = reinterpret_cast<const float4*>(input)[idx / 4];
        float vals[4] = {v.x, v.y, v.z, v.w};
        #pragma unroll
        for (int i = 0; i < 4; i++) {
            float s = vals[i] * inv_divisor;
            float cube = s * s * s;
            vals[i] = 0.5f * s * (1.0f + tanhf(0.7978845608f * (s + 0.044715f * cube)));
        }
        float4 out;
        out.x = vals[0]; out.y = vals[1]; out.z = vals[2]; out.w = vals[3];
        reinterpret_cast<float4*>(output)[idx / 4] = out;
    } else {
        for (int i = idx; i < numel && i < idx + 4; i++) {
            float s = input[i] * inv_divisor;
            float cube = s * s * s;
            output[i] = 0.5f * s * (1.0f + tanhf(0.7978845608f * (s + 0.044715f * cube)));
        }
    }
}

static torch::Tensor fallback_matmul_divide_gelu(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double divisor) {
    // x: [M, K], weight: [N, K] -> out: [M, N]
    auto out = torch::matmul(x, weight.t());
    if (bias.defined() && bias.numel() > 0) {
        out = out + bias;
    }
    int numel = out.numel();
    float inv_divisor = 1.0f / static_cast<float>(divisor);
    auto out_contig = out.contiguous();
    auto result = torch::empty_like(out_contig);
    int threads = 256;
    int blocks = (numel + threads * 4 - 1) / (threads * 4);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    divide_gelu_kernel<<<blocks, threads, 0, stream>>>(
        out_contig.data_ptr<float>(),
        result.data_ptr<float>(),
        numel,
        inv_divisor
    );
    return result;
}

torch::Tensor matmul_divide_gelu_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double divisor) {

    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D");
    TORCH_CHECK(x.size(1) == weight.size(1), "x.size(1) must equal weight.size(1) (K dimension)");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    int64_t M = x_c.size(0);
    int64_t K = x_c.size(1);
    int64_t N = w_c.size(0);

    auto out = torch::empty({M, N}, x_c.options());

    cublasLtHandle_t ltHandle;
    if (cublasLtCreate(&ltHandle) != CUBLAS_STATUS_SUCCESS) {
        return fallback_matmul_divide_gelu(x_c, w_c, bias, divisor);
    }

    cublasLtMatmulDesc_t operationDesc = nullptr;
    cublasLtMatrixLayout_t Adesc = nullptr, Bdesc = nullptr, Cdesc = nullptr;
    cublasLtMatmulPreference_t preference = nullptr;
    void* workspace = nullptr;
    size_t workspaceSize = 32 * 1024 * 1024; // 32 MB workspace

    bool cublaslt_ok = false;

    do {
        if (cublasLtMatmulDescCreate(&operationDesc, CUBLAS_COMPUTE_32F, CUDA_R_32F) != CUBLAS_STATUS_SUCCESS) break;

        // Determine epilogue: use GELU_BIAS if bias is provided, else GELU
        bool has_bias = bias.defined() && bias.numel() > 0;
        cublasLtEpilogue_t epilogue = has_bias ? CUBLASLT_EPILOGUE_GELU_BIAS : CUBLASLT_EPILOGUE_GELU;
        if (cublasLtMatmulDescSetAttribute(operationDesc,
            CUBLASLT_MATMUL_DESC_EPILOGUE,
            &epilogue, sizeof(epilogue)) != CUBLAS_STATUS_SUCCESS) break;

        if (has_bias) {
            auto bias_c = bias.contiguous();
            const void* bias_ptr = bias_c.data_ptr<float>();
            if (cublasLtMatmulDescSetAttribute(operationDesc,
                CUBLASLT_MATMUL_DESC_BIAS_POINTER,
                &bias_ptr, sizeof(bias_ptr)) != CUBLAS_STATUS_SUCCESS) break;
        }

        // A = x [M, K] row-major, transa = N
        // B = weight [N, K] row-major, transb = T (we want weight^T)
        // C = out [M, N] row-major
        // cuBLAS column-major: we compute C^T = B * A^T
        // So in col-major: A_col = out [N, M], B_col = weight [N, K], C_col = x [K, M]
        // Equivalently: treat everything in row-major by swapping A and B roles:
        // out [M,N] row-major = x[M,K] * weight^T[K,N]
        // In cuBLAS col-major: out_col[N,M] = weight[N,K] * x_col[K,M]
        // So: A_cublaslt = weight (no transpose), B_cublaslt = x (no transpose)
        // leading dims in col-major: ldA = N (weight leading dim), ldB = K (x leading dim), ldC = N (out leading dim)

        cublasOperation_t transa = CUBLAS_OP_N;
        cublasOperation_t transb = CUBLAS_OP_N;
        if (cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_TRANSA, &transa, sizeof(transa)) != CUBLAS_STATUS_SUCCESS) break;
        if (cublasLtMatmulDescSetAttribute(operationDesc, CUBLASLT_MATMUL_DESC_TRANSB, &transb, sizeof(transb)) != CUBLAS_STATUS_SUCCESS) break;

        // A = weight: shape [N, K], col-major leading dim = N
        if (cublasLtMatrixLayoutCreate(&Adesc, CUDA_R_32F, N, K, N) != CUBLAS_STATUS_SUCCESS) break;
        // B = x: shape [K, M], col-major leading dim = K
        if (cublasLtMatrixLayoutCreate(&Bdesc, CUDA_R_32F, K, M, K) != CUBLAS_STATUS_SUCCESS) break;
        // C = out: shape [N, M], col-major leading dim = N
        if (cublasLtMatrixLayoutCreate(&Cdesc, CUDA_R_32F, N, M, N) != CUBLAS_STATUS_SUCCESS) break;

        if (cublasLtMatmulPreferenceCreate(&preference) != CUBLAS_STATUS_SUCCESS) break;
        if (cudaMalloc(&workspace, workspaceSize) != cudaSuccess) {
            workspaceSize = 0;
            workspace = nullptr;
        }
        if (cublasLtMatmulPreferenceSetAttribute(preference,
            CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
            &workspaceSize, sizeof(workspaceSize)) != CUBLAS_STATUS_SUCCESS) break;

        cublasLtMatmulHeuristicResult_t heuristicResult = {};
        int returnedResults = 0;
        if (cublasLtMatmulAlgoGetHeuristic(ltHandle, operationDesc,
            Adesc, Bdesc, Cdesc, Cdesc,
            preference, 1, &heuristicResult, &returnedResults) != CUBLAS_STATUS_SUCCESS) break;
        if (returnedResults == 0) break;

        float alpha = 1.0f / static_cast<float>(divisor);
        float beta = 0.0f;
        cudaStream_t stream = at::cuda::getCurrentCUDAStream();

        if (cublasLtMatmul(ltHandle, operationDesc,
            &alpha,
            w_c.data_ptr<float>(), Adesc,
            x_c.data_ptr<float>(), Bdesc,
            &beta,
            out.data_ptr<float>(), Cdesc,
            out.data_ptr<float>(), Cdesc,
            &heuristicResult.algo,
            workspace, workspaceSize,
            stream) != CUBLAS_STATUS_SUCCESS) break;

        cublaslt_ok = true;
    } while(false);

    if (preference) cublasLtMatmulPreferenceDestroy(preference);
    if (Cdesc) cublasLtMatrixLayoutDestroy(Cdesc);
    if (Bdesc) cublasLtMatrixLayoutDestroy(Bdesc);
    if (Adesc) cublasLtMatrixLayoutDestroy(Adesc);
    if (operationDesc) cublasLtMatmulDescDestroy(operationDesc);
    if (workspace) cudaFree(workspace);
    cublasLtDestroy(ltHandle);

    if (!cublaslt_ok) {
        return fallback_matmul_divide_gelu(x_c, w_c, bias, divisor);
    }
    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        A model that performs a matrix multiplication, divides by a scalar, and applies GELU activation.
        """
    def __init__(self, input_size, output_size, divisor):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, input_size).
                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, output_size).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda and x.dtype == torch.float32 and self.linear.weight.dtype == torch.float32 and x.dim() == 2:
            bias_tensor = self.linear.bias.contiguous() if self.linear.bias is not None else self.linear.weight.new_empty(0)
            x = _stark_get_extension().matmul_divide_gelu(
            x.contiguous(),
            self.linear.weight.contiguous(),
            bias_tensor,
            float(self.divisor)
            )
            return x
        else:
            x = self.linear(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        x = x / self.divisor
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        x = torch.nn.functional.gelu(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
        # <<<END_IMPROVE>>>

