struct CublasLtState {
    cublasLtHandle_t handle = nullptr;
    void*            workspace = nullptr;
    size_t           workspace_bytes = 0;
    bool             initialized = false;
    bool             failed = false;   // if init failed, fall back forever
};

static CublasLtState g_lt_state;
static std::mutex    g_lt_mutex;

static bool ensure_lt_state(size_t ws_bytes = 32ULL * 1024 * 1024) {
    if (g_lt_state.initialized) return !g_lt_state.failed;
    std::lock_guard<std::mutex> lk(g_lt_mutex);
    if (g_lt_state.initialized) return !g_lt_state.failed;
    g_lt_state.initialized = true;
    if (cublasLtCreate(&g_lt_state.handle) != CUBLAS_STATUS_SUCCESS) {
        g_lt_state.failed = true; return false;
    }
    if (cudaMalloc(&g_lt_state.workspace, ws_bytes) == cudaSuccess) {
