                CUBLAS_COMPUTE_32F, CUDA_R_32F) != CUBLAS_STATUS_SUCCESS) break;

        // We compute (row-major): out[M,N] = x[M,K] * weight^T[K,N]
        // In cuBLAS column-major equivalence:
        //   out_col[N,M] = weight[N,K] * x_col[K,M]
        // So: A = weight (no-T), B = x (no-T), C = out
        // ldA = N (weight leading dim in col-major), ldB = K, ldC = N
        cublasOperation_t transa = CUBLAS_OP_N;
        cublasOperation_t transb = CUBLAS_OP_N;
        if (cublasLtMatmulDescSetAttribute(operationDesc,
                CUBLASLT_MATMUL_DESC_TRANSA, &transa, sizeof(transa)) != CUBLAS_STATUS_SUCCESS) break;
        if (cublasLtMatmulDescSetAttribute(operationDesc,
                CUBLASLT_MATMUL_DESC_TRANSB, &transb, sizeof(transb)) != CUBLAS_STATUS_SUCCESS) break;

