            ? CUBLASLT_EPILOGUE_GELU_BIAS
            : CUBLASLT_EPILOGUE_GELU;
        if (cublasLtMatmulDescSetAttribute(operationDesc,
                CUBLASLT_MATMUL_DESC_EPILOGUE,
                &epilogue, sizeof(epilogue)) != CUBLAS_STATUS_SUCCESS) break;

        if (has_bias) {
            // bias vector length must be N (output features)
