        if (cublasLtMatrixLayoutCreate(&Bdesc, CUDA_R_32F, K, M, K) != CUBLAS_STATUS_SUCCESS) break;
        if (cublasLtMatrixLayoutCreate(&Cdesc, CUDA_R_32F, N, M, N) != CUBLAS_STATUS_SUCCESS) break;

        if (cublasLtMatmulPreferenceCreate(&preference) != CUBLAS_STATUS_SUCCESS) break;
        if (cublasLtMatmulPreferenceSetAttribute(preference,
                CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
                &g_lt_state.workspace_bytes,
                sizeof(g_lt_state.workspace_bytes)) != CUBLAS_STATUS_SUCCESS) break;

